for i in r['ids']:
 k=str(i);q=prov[k];d=q['record'];q['statement_utf8_sha256']=h(d['statement'].encode());status,depth,attempt,gap=notes[i]
 files=sorted(f for f in (p/'sources').iterdir() if f.name.startswith(k+'-'))
 results[k]={'mathdb_id':i,'title':d['title'],'literal_statement':d['statement'],'full_record_file':f'records/{i}.json','provenance':{z:v for z,v in q.items() if z!='record'},'disposition':status,'review_depth':depth,'ordinary_attempt':attempt,'precise_gap_or_exclusion':gap,'source_files':[{'path':str(f.relative_to(p)),'sha256':h(f.read_bytes())} for f in files],'version_review_limit':'All versions listed on fetched primary abstract pages were downloaded and text-indexed for the 17 original arXiv sources; target locator windows are retained. This is not an independent full-proof reading of every version.','historical_review':'Bounded frontier md/results/review scan and exact structured-match validation; no direct assigned-ID entries in matched structured files. Digit substrings in hashes are not historical reviews. Whole authored tree and all old lane notes not exhaustively read.','journal_citing_figure_limit':'Only the explicitly named bodies/passages and Lin Figure 2 were read. No complete journal/corrections/citation closure or all-figure audit.','registry_limit':'Current public HTML heads captured for OpenAI math and Formal Conjectures. No complete current tree/body audit; leanpool/project URL attempts were 404. No API requests or bypass.','qualification':'No source-qualified new full-scope proof/counterexample or Pi execution assignment.','credit':0,'lean_executed':False}
