(p/'reservation-after.json').write_text(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sha256':expected,'verified':True,'same_as_before':True,'exact_20_result_keys':True},indent=2)+'\n')
