for f in sorted((p/'sources').iterdir()):inv.append({'path':str(f.relative_to(p)),'bytes':f.stat().st_size,'sha256':h(f.read_bytes()),'read_depth':'See per-ID results and ORDINARY-ATTEMPTS; download/text index is not proof reading.'})
